window.__census = async (name) => {
  const app = window.__CITY_APP, r = app.renderer, scene = app.scene;
  const raf = () => new Promise((res) => requestAnimationFrame(res));
  const stack = [], frames = new Map();
  const origDirect = r._renderObjectDirect, origUpdate = r.info.update;
  const rootOf = (o) => { while (o.parent && o.parent !== scene) o = o.parent; return o.name || o.type; };
  r._renderObjectDirect = function (object, material, sc, camera) {
    const pass = sc === scene ? (camera.isOrthographicCamera ? 'shadow' : 'main') : 'other';
    let root = sc === scene ? rootOf(object) : (object.name || object.type);
    if (root === 'Trees') { const m = /_(near|mid|far)/.exec(object.name || '') || /(card|crown)/i.exec(object.name || ''); root += '/' + (m ? m[1] : (object.name || '?')); }
    stack.push([pass, root]);
    try { return origDirect.apply(this, arguments); } finally { stack.pop(); }
  };
  r.info.update = function (object, count, instanceCount) {
    const [pass, root] = stack[stack.length - 1] || ['unlabelled', '?'];
    const f = app.frameNo; let fr = frames.get(f); if (!fr) frames.set(f, fr = { passes: {}, roots: {} });
    const tri = (object.isMesh || object.isSprite) ? instanceCount * count / 3 : 0;
    const p = fr.passes[pass] || (fr.passes[pass] = { draws: 0, triangles: 0 }); p.draws++; p.triangles += tri;
    const k = pass + ' ' + root; const q = fr.roots[k] || (fr.roots[k] = { draws: 0, triangles: 0 }); q.draws++; q.triangles += tri;
    return origUpdate.apply(this, arguments);
  };
  const f0 = app.frameNo; while (app.frameNo < f0 + 4) await raf();
  r._renderObjectDirect = origDirect; delete r._renderObjectDirect; r.info.update = origUpdate; delete r.info.update;
  const keys = [...frames.keys()].sort((a, b) => a - b); const fr = frames.get(keys[Math.floor(keys.length / 2)]);
  let objects = 0, visible = 0, meshes = 0, autoUpd = 0; scene.traverse((o) => { objects++; if (o.isMesh) { meshes++; if (o.matrixAutoUpdate) autoUpd++; } }); scene.traverseVisible(() => visible++);
  const umw = []; let umwTotal = 0;
  for (const c of scene.children) { let n = 0; c.traverse(() => n++); const t = performance.now(); for (let k = 0; k < 20; k++) c.updateMatrixWorld(); const ms = (performance.now() - t) / 20; umwTotal += ms; umw.push({ root: c.name || c.type, objects: n, ms: +ms.toFixed(3), frozen: c.updateMatrixWorld.toString().length < 20 }); }
  const t1 = performance.now(); for (let k = 0; k < 20; k++) scene.updateMatrixWorld(); const sceneUmwMs = +((performance.now() - t1) / 20).toFixed(3);
  umw.sort((a, b) => b.ms - a.ms);
  const top = Object.entries(fr.roots).sort((a, b) => b[1].triangles - a[1].triangles).slice(0, 40).map(([k, v]) => ({ k, draws: v.draws, ktris: Math.round(v.triangles / 1000) }));
  const total = Object.values(fr.passes).reduce((a, p) => ({ draws: a.draws + p.draws, triangles: a.triangles + p.triangles }), { draws: 0, triangles: 0 });
  const res = { name, framesSeen: keys.length, frameUsed: keys[Math.floor(keys.length / 2)], tier: CITY.QUALITY.tier, canvas: [r.domElement.width, r.domElement.height],
    passes: fr.passes, total, rendererInfoLastFrame: { drawCalls: r.info.render.drawCalls, triangles: r.info.render.triangles },
    shadowMapSize: app.lightingSystem?.sunLight?.shadow?.mapSize?.x, shadowFar: app.lightingSystem?.sunLight?.shadow?.camera?.far,
    sceneObjects: objects, visibleWalk: visible, meshes, meshesWithMatrixAutoUpdate: autoUpd, cullingStats: app.cullingStats, sceneUpdateMatrixWorldMs: sceneUmwMs, updateMatrixWorldByRoot: umw.slice(0, 25), top };
  console.log('[census] ' + JSON.stringify({ name, passes: fr.passes, total }));
  return res;
};
